// Batch 6: office shenanigans (career), money schemes (assets), love & family chaos (relations).
// Actions have no actor: relationship effects on whole groups go through the small `fn` helpers below.
import type { ActionDef, Effect, EffectCtx, RoleSel } from '@bl/sim';
import { clamp, living } from '@bl/sim';

/** Changes the relationship gauge of every living NPC matching `roles`. */
const relAll = (roles: RoleSel | RoleSel[], d: number): Effect => ({
  fn: ({ life }: EffectCtx) => { for (const n of living(life, roles)) n.rel = clamp(n.rel + d); },
});

/** Same pregnancy mechanic as the per-NPC "Try for a baby" interaction (birth next year). */
const baby = (): Effect => ({
  fn: ({ life }: EffectCtx) => {
    life.flags.pregnant = life.age;
    const other = living(life, 'lover')[0];
    if (other) life.flags.babyWith = other.id;
  },
});

/** The current partner / fiancé(e) / spouse becomes an ex. */
const dumped = (): Effect => ({
  fn: ({ life }: EffectCtx) => { const n = living(life, 'lover')[0]; if (n) { n.role = 'ex'; n.rel = clamp(n.rel - 40); } },
});

/** Adopted child: takes my last name and starts out liking me. */
const adoptFx: Effect = {
  newNpc: { role: 'child', age: [0, 8], abs: true, gender: 'any' },
  fn: ({ life }: EffectCtx) => { const k = life.npcs[life.npcs.length - 1]; if (k && k.role === 'child') { k.last = life.last; k.rel = 75; } },
};

